Function pesos <- PrecioEnPesos(dolares As Integer, cambio As Integer)
  Define pesos As Integer;
  pesos <- dolares * cambio;
EndFunction

Algorithm Precio
  Define dolares As Integer;
  Define cambio As Integer;
  Read dolares;
  Read cambio;
  Write PrecioEnPesos(dolares, cambio);
EndAlgorithm
